using MelloSilveiraTools.Mathematics.Factories.Functions;
using MelloSilveiraTools.Mathematics.Functions;
using MelloSilveiraTools.MechanicsOfMaterials.Calculators.MechanicalModels.Viscoelasticity.NonLinear.Schapery;
using MelloSilveiraTools.MechanicsOfMaterials.Optimizations.CurveFitting.Algorithms;
using MelloSilveiraTools.MechanicsOfMaterials.Optimizations.CurveFitting.MathematicalFunctions;
using MelloSilveiraTools.MechanicsOfMaterials.Optimizations.Pipelines.ExperimentalData.Steps.CurveFitter;
using Microsoft.Extensions.Logging;
using Moq;

namespace UnitTests;

public class SchaperyRelaxationOnlyCurveFitterStepTests
{
    private static readonly AlglibCurveFitter _alglibCurveFitter = new();
    private static readonly MathNetCurveFitter _mathNetCurveFitter = new();

    private readonly SchaperyRelaxationOnlyCurveFitterStep _stepWithAlglib = new(
        Mock.Of<ILogger<SchaperyRelaxationOnlyCurveFitterStep>>(),
        Mock.Of<ISchaperyModelCalculator>(),
        _alglibCurveFitter,
        new LogarithmicCurveFitter(_alglibCurveFitter),
        new ExponentialCurveFitter(_alglibCurveFitter),
        new FunctionFactory()
    );

    private readonly SchaperyRelaxationOnlyCurveFitterStep _stepWithMathNet = new(
        Mock.Of<ILogger<SchaperyRelaxationOnlyCurveFitterStep>>(),
        Mock.Of<ISchaperyModelCalculator>(),
        _mathNetCurveFitter,
        new LogarithmicCurveFitter(_mathNetCurveFitter),
        new ExponentialCurveFitter(_mathNetCurveFitter),
        new FunctionFactory()
    );

    [Theory]
    [MemberData(nameof(GetHelmholtzDataAlglib))]
    public void FitHelmholtzVariable_FitWithAlglib_ShouldSelectBestFunction(double[] strains, double[] heValues, double[] h2Values, double[] expectedHeConstants, double[] expectedH2Constants, double expectedHeError, double expectedH2Error, int expectedHeIterations, int expectedH2Iterations)
    {
        // Act
        // Validating the user's premise: both arrays CAN successfully fit an exponential function.
        var heResult = _stepWithAlglib.FitHelmholtzVariable(strains, heValues);
        var h2Result = _stepWithAlglib.FitHelmholtzVariable(strains, h2Values);
        Function heFunction = heResult.Function;
        Function h2Function = h2Result.Function;

        // Assert
        Assert.NotNull(heFunction);
        Assert.NotNull(h2Function);

        Assert.Equal(expectedHeConstants.Length, heFunction.Coefficients.Length);
        Assert.Equal(expectedH2Constants.Length, h2Function.Coefficients.Length);

        // GDEMO is a stochastic genetic algorithm, exact constants and error cannot be asserted.
        // We assert that the found error is reasonably close to or better than the original deterministic minimum.
        Assert.True(heResult.Error <= expectedHeError + 0.05, $"HeError {heResult.Error} > {expectedHeError}");
        Assert.True(h2Result.Error <= expectedH2Error + 0.05, $"H2Error {h2Result.Error} > {expectedH2Error}");
    }

    [Theory]
    [MemberData(nameof(GetHelmholtzDataMathNet))]
    public void FitHelmholtzVariable_FitWithMathNet_ShouldSelectBestFunction(double[] strains, double[] heValues, double[] h2Values, double[] expectedHeConstants, double[] expectedH2Constants, double expectedHeError, double expectedH2Error, int expectedHeIterations, int expectedH2Iterations)
    {
        // Act
        // Validating the user's premise: both arrays CAN successfully fit an exponential function.
        var heResult = _stepWithMathNet.FitHelmholtzVariable(strains, heValues);
        var h2Result = _stepWithMathNet.FitHelmholtzVariable(strains, h2Values);
        Function heFunction = heResult.Function;
        Function h2Function = h2Result.Function;

        // Assert
        Assert.NotNull(heFunction);
        Assert.NotNull(h2Function);

        Assert.Equal(expectedHeConstants.Length, heFunction.Coefficients.Length);
        for (int i = 0; i < expectedHeConstants.Length; i++) Assert.Equal(expectedHeConstants[i], heFunction.Coefficients[i], 3);

        Assert.Equal(expectedH2Constants.Length, h2Function.Coefficients.Length);
        for (int i = 0; i < expectedH2Constants.Length; i++) Assert.Equal(expectedH2Constants[i], h2Function.Coefficients[i], 3);

        Assert.Equal(expectedHeError, heResult.Error, 3);
        Assert.Equal(expectedH2Error, h2Result.Error, 3);

        Assert.Equal(expectedHeIterations, heResult.Iterations);
        Assert.Equal(expectedH2Iterations, h2Result.Iterations);
    }

